NotaryLaws.register({"id":"zvevro","abbr":"ЗВЕРБ","title":{"bg":"Закон за въвеждане на еврото в Република България (извадка)","en":"Act on the Introduction of the Euro in the Republic of Bulgaria (extract)"},"group":"tax","source":"https://lex.bg/laws/ldoc/2137244903","retrieved":"2026-10-21","partial":true,"articles":14,"inForce":"","published":"Обн. ДВ. бр.70 от 20 Август 2024г.","lastChange":"изм. и доп. ДВ. бр.92 от 6 Октомври 2026г.","items":[{"k":"h","t":"Глава първа. ОБЩИ ПОЛОЖЕНИЯ"},{"k":"s","t":"Раздел I. Предмет, цел и основни положения"},{"k":"a","n":"1","p":["Чл. 1. Този закон осигурява прилагането на съответните актове на Европейския съюз, като определя необходимите мерки на национално ниво за въвеждане на еврото в Република България."],"t":"Предмет"},{"k":"a","n":"2","p":["Чл. 2. Целта на закона е да допълни и улесни въвеждането на еврото в Република България и да повиши прозрачността и информираността за процеса на въвеждане на еврото в страната в съответствие с пряко приложимото право на Европейския съюз."],"t":"Цел"},{"k":"a","n":"3","p":["Чл. 3. (Изм. - ДВ, бр. 65 от 2025 г.) Дата на въвеждане на еврото в Република България е датата, определена в Решение на Съвета на Европейския съюз за приемането на еврото от Република България, прието в съответствие с чл. 140, параграф 2 от Договора за функционирането на Европейския съюз, и Регламент на Съвета на Европейския съюз, приет в съответствие с чл. 140, параграф 3 от Договора за функционирането на Европейския съюз."],"t":"Дата на въвеждане на еврото в Република България"},{"k":"a","n":"4","p":["Чл. 4. В съответствие с чл. 2 от Регламент (ЕО) № 974/98 на Съвета от 3 май 1998 г. относно въвеждането на еврото, наричан по-нататък \"Регламент (ЕО) № 974/98\", считано от датата на въвеждане на еврото в Република България, валутата на Република България е еврото. Паричната единица е едно евро. Едно евро се разделя на сто цента."],"t":"Официална парична единица"},{"k":"a","n":"5","p":["Чл. 5. Официалният валутен курс на лева към еврото е неотменимо фиксираният валутен курс на лева към еврото, определен в Регламент на Съвета, приет в съответствие с чл. 140, параграф 3 от Договора за функционирането на Европейския съюз."],"t":"Официален валутен курс"},{"k":"s","t":"Раздел II. Основни принципи и правила"},{"k":"a","n":"6","p":["Чл. 6. В процеса на въвеждане на еврото в Република България се прилагат принципът на защита на потребителите, принципът на информираност, принципът на ефективност и икономичност, принципът на прозрачност и принципът на приемственост и автоматично превалутиране на суми от левове в евро."],"t":"Принципи"},{"k":"a","n":"7","p":["Чл. 7. (1) Превалутирането на цените и другите стойности от левове в евро не може да води до поставяне на потребителите във финансово по-неблагоприятно положение, отколкото биха били, ако еврото не е въведено като парична единица на Република България, в съответствие с приложимите актове на Европейския съюз в областта на защитата на потребителите.","(2) Въвеждането на еврото не може да води до увеличение на цените на стоките и услугите, освен когато това е обосновано от обективни икономически фактори."],"t":"Принцип на защита на потребителите"},{"k":"a","n":"8","p":["Чл. 8. На потребителите се предоставя ясна, точна и своевременна информация за принципите, правилата и процедурите за въвеждане на еврото като парична единица на Република България, включително реда и правилата за обмяната на левове в евро, превалутирането от левове в евро и представянето на цените на стоки и услуги, и на други стойности в евро."],"t":"Принцип на информираност"},{"k":"a","n":"9","p":["Чл. 9. (1) Въвеждането на еврото като парична единица на Република България и всички произтичащи от това процедури и дейности се извършват по най-ефективен и целесъобразен начин, в съответствие с приложимите актове на Европейския съюз в областта на защита на потребителите, като разходите за лицата не се компенсират с публични средства.","(2) Изискванията за одобрение от държавен орган не се прилагат, когато измененията в устави, дружествени договори, учредителни актове, правила, процедури и други вътрешни актове или договори, свързани с извършване на дейност или предоставяне на услуги, се налагат от въвеждането на еврото в страната и са свързани само с превалутиране на стойности от левове в евро."],"t":"Принцип на ефективност и икономичност"},{"k":"a","n":"10","p":["Чл. 10. Процесът по въвеждането на еврото като парична единица на Република България следва да бъде извършен по прозрачен начин, като отговорните институции, органи и лица предоставят публично своевременна, подробна, ясна, точна и разбираема информация."],"t":"Принцип на прозрачност"},{"k":"a","n":"11","p":["Чл. 11. (1) В съответствие с Регламент (ЕО) № 974/98 и другото пряко приложимо право на Европейския съюз въвеждането на еврото не засяга действието на съществуващите правни инструменти с позовавания на лева или с препратки към лева.","(2) В съответствие с чл. 6 - 9 от Регламент (ЕО) № 974/98 стойностите, посочени в левове в съществуващите правни инструменти, се считат за стойности в евро при прилагане на официалния валутен курс и правилата за превалутиране по чл. 12 и съответно за закръгляване по чл. 13 или по специалните правила за закръгляване, предвидени в този закон.","(3) В съответствие с чл. 3 от Регламент (ЕО) № 1103/97 на Съвета от 17 юни 1997 г. относно определени разпоредби, отнасящи се до въвеждането на еврото, наричан по-нататък \"Регламент (ЕО) № 1103/97\", въвеждането на еврото няма за последица промяна на никой от сроковете в правен инструмент или освобождаване от задължение или изпълнение съгласно който и да е правен инструмент, нито дава право на страна едностранно да измени или прекрати такъв инструмент. Тази алинея се прилага, без да се засяга договореното между страните.","(4) В съответствие с чл. 6, параграф 2 от Регламент (ЕО) 974/98 позоваванията в правните инструменти на лева без посочване на стойността се считат за позовавания на еврото."],"t":"Принцип на приемственост и автоматично превалутиране на суми от левове в евро"},{"k":"a","n":"12","p":["Чл. 12. (1) В съответствие с чл. 4 от Регламент (ЕО) № 1103/97 превалутирането от левове в евро се извършва, като числовата стойност в левове се раздели на пълната числова стойност на официалния валутен курс, изразен с шест цифри с всичките пет знака след десетичната запетая.","(2) Официалният валутен курс не се закръглява или съкращава при извършването на превалутирането."],"t":"Правило за превалутиране от левове в евро"},{"k":"a","n":"13","p":["Чл. 13. (1) В съответствие с чл. 4 и 5 от Регламент (ЕО) 1103/97 след превалутиране съгласно чл. 12 получената сума се закръглява до втория знак след десетичната запетая на базата на третия знак след десетичната запетая в съответствие със следното математическо правило за закръгляване:","1. когато третият знак след десетичната запетая е по-малък от пет, вторият знак след десетичната запетая остава непроменен;","2. когато третият знак след десетичната запетая е равен на или по-голям от пет, вторият знак след десетичната запетая се увеличава с една единица.","(2) Изключение от правилото по ал. 1 относно знака след десетичната запетая, на базата на който се извършва закръгляването, се допуска само когато този или друг закон или правен акт на Европейския съюз предвиждат закръгляването да се извършва до знак след десетичната запетая, различен от посочения в ал. 1."],"t":"Правило за закръгляване"},{"k":"s","t":"Раздел III. Достъп до информация"},{"k":"a","n":"14","p":["Чл. 14. (1) В период от една година от датата на въвеждане на еврото в Република България всяко лице има право да получи информация относно паричните стойности в левове на негови имуществени права и задължения към датата на превалутиране.","(2) Лицата, извършили превалутиране по реда на този закон, предоставят безплатно информацията по ал. 1 в 7-дневен срок от поискването."],"t":"Право на информация"}]});
